test('preValidation hook should support encapsulation / 3', async t => {
  t.plan(19)
  const fastify = Fastify()
  t.after(() => { fastify.close() })
  fastify.decorate('hello', 'world')

  fastify.addHook('preValidation', function (req, reply, done) {
